#pragma once
// Sprite-only intro: apple -> hand -> earth -> man over the city -> eyes -> title (city sprites stay under the title).
// Every scene is 4bpp OBJ tiles + block tables + keyframes (generated by tools/make_intro.py -> intro_data.c).
#include "gba.h"
typedef struct { s16 cx, cy; u16 tile, bank; } IBlk;                 // block centre relative to layer centre
typedef struct { s16 t, x, y, sc, ang, ease; } IKey;                 // frame, screen pos, scale (Q8), angle (256=turn), smoothstep-to-next
typedef struct { const IBlk *blk; u8 n, shape, size; int8_t grp; u8 dbl; const IKey *keys; u8 nkeys; } ILayer;
typedef struct { const u32 *tiles; u16 nwords; const u16 *pal; const ILayer *layers; u8 nlayers; u16 frames, fin, fout, backdrop; u8 flags; } IScene;   // flags bit0: fade OUT to white instead of black
extern const IScene intro_scenes[];
extern const int INTRO_SCENES;
extern const int INTRO_TITLE_HOLD, INTRO_TITLE_CYCLE;               // skyline loop: frames per pose / per ping-pong cycle
extern const s16 sin256[256];
#define OBJ_ON 0x1040                                                /* OBJ layer + 1-D tile mapping (mode 0) */
void intro_build(const IScene *S, int t, u16 *oam);                  // pure: fills a 512-halfword OAM image (host-testable)
void intro_play(void);                                               // blocking; leaves the city sprites resident for the title
void intro_title_tick(int frame);                                    // once per frame on the title screen: steps the 4-frame skyline loop
void intro_reload_title(void);                                       // re-upload the title skyline tiles (menu's bitmap pages overwrite part of OBJ VRAM)
